import{_ as d,o as l,c as a,a1 as i}from"./chunks/framework.CZNLRqm4.js";const b=JSON.parse('{"title":"人生规划","description":"","frontmatter":{},"headers":[],"relativePath":"My-Study-career.md","filePath":"My-Study-career.md"}'),r={name:"My-Study-career.md"};function e(o,t,n,h,s,u){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="人生规划" tabindex="-1">人生规划 <a class="header-anchor" href="#人生规划" aria-label="Permalink to &quot;人生规划&quot;">​</a></h1><h2 id="一、一年目标与安排" tabindex="-1">一、一年目标与安排 <a class="header-anchor" href="#一、一年目标与安排" aria-label="Permalink to &quot;一、一年目标与安排&quot;">​</a></h2><ul><li>核心：<strong>赚钱 + 自我提升</strong>。</li></ul><h2 id="二、自我提升" tabindex="-1">二、自我提升 <a class="header-anchor" href="#二、自我提升" aria-label="Permalink to &quot;二、自我提升&quot;">​</a></h2><h3 id="_1-英语" tabindex="-1">1. 英语 <a class="header-anchor" href="#_1-英语" aria-label="Permalink to &quot;1. 英语&quot;">​</a></h3><ul><li>英语最重要，要作为重心。</li><li>目标：雅思 <strong>6.5 以上</strong>。</li><li>预计需要一年时间（2026年9月开始）</li><li>重点：<strong>阅读 + 口语</strong>。</li><li>我考的是公共学术类，平时多认识单词。口语：在课堂上，或者……每天进行单词和口语练习。</li></ul><h3 id="_2-物理-专业录课" tabindex="-1">2. 物理 / 专业录课 <a class="header-anchor" href="#_2-物理-专业录课" aria-label="Permalink to &quot;2. 物理 / 专业录课&quot;">​</a></h3><ul><li>从初中物理开始录课，而后跳至大学课程，主要做电脑录课。</li><li>因为扩大个人影响力很重要。</li><li>还要去看一些物理学前沿科研班。</li><li>我的物理专业领域也还得听课和自学。</li></ul><h3 id="_3-专业技术线" tabindex="-1">3. 专业技术线 <a class="header-anchor" href="#_3-专业技术线" aria-label="Permalink to &quot;3. 专业技术线&quot;">​</a></h3><ul><li>看文件夹说的，AI情绪行业</li><li></li></ul><p><strong>配件+情绪行业调研整理归纳</strong></p><p><strong>一、调研与验证</strong> 先做调研报告，厘清：是否有需求、需求量或市场有多大；必须举出成功先例，有过市场反响。基于调研确定做怎样的产品，给出 demo，并预测市场反应；同时研究产品实现的技术栈难度，给出具体设想思路。</p><p><strong>二、产品与初心</strong> 每一款产品都要与最初愿景或初心高度一致，符合整体链条，最终形成口碑和品牌效应，也许还应开源。</p><p><strong>三、行业选择与商业模式</strong> 进入配件行业，即成为别人的附属。</p><ul><li>好处：能依赖原有大体量用户，精准对产品进行销售。</li><li>坏处：容易被取代，商品无法形成长期收益。 因此后续必须开源设计，转为营销手段而非获利手段；过程中可能让利消费者，也可能存在背刺消费者的风险。前期以求生存为主，而非追求名誉。</li></ul><p><strong>四、配件分类</strong></p><ul><li><strong>实体配件</strong>： <ul><li>手机配件：外置延伸摄像头、手机控制零件；</li><li>无人机配件：天线、灯光模块、高频头等；</li><li>摩托车配件：手机支架、个性灯光等。</li></ul></li><li><strong>虚拟配件</strong>： <ul><li>AI 中的定制 skill、个性化调教、语言调节处理；</li><li>个性化定制 APP 等。</li></ul></li></ul><p><strong>五、情绪强关联</strong> 必须做配件和情绪强关联的产品。 情绪是人天生带有，由周遭事物影响，也可通过周遭事物表达，包括喜怒哀乐等。配件既可承载情绪，也可宣泄情绪。</p><p><strong>六、从情绪到情感与价值</strong> 情绪更深层次是情感。配件可以是情感的枢纽：连接人与人之间的情感，或人与世界的情感枢纽作用。 因此，<strong>情绪 + 配件 = 枢纽</strong>。当物品被赋予故事和情感，就成为重要的枢纽作用物品，也即被赋予价值。</p><p><strong>七、核心结论</strong> 一件好卖的产品应具有价值；如何赋予价值、赋予怎样的价值，是故事的起点。 整体逻辑：先调研验证需求与市场，做与初心一致的配件产品；以实体/虚拟配件切入，依附大平台求生存；因易被取代，后续以开源设计转为营销手段；核心差异在于情绪与情感价值，把配件做成承载故事、情感和价值的枢纽。</p><h3 id="_4-思想深度" tabindex="-1">4. 思想深度 <a class="header-anchor" href="#_4-思想深度" aria-label="Permalink to &quot;4. 思想深度&quot;">​</a></h3><ul><li>多看哲学书，输出形成自己的成果，然后发布在网站上。</li></ul><h3 id="_5-网站-博客" tabindex="-1">5. 网站 / 博客 <a class="header-anchor" href="#_5-网站-博客" aria-label="Permalink to &quot;5. 网站 / 博客&quot;">​</a></h3><ul><li>已完成</li></ul><h2 id="三、时间规划" tabindex="-1">三、时间规划 <a class="header-anchor" href="#三、时间规划" aria-label="Permalink to &quot;三、时间规划&quot;">​</a></h2><ul><li>完成工作就直接干自己的事情。</li><li>每天得设定任务才行。</li></ul><h3 id="每日安排" tabindex="-1">每日安排 <a class="header-anchor" href="#每日安排" aria-label="Permalink to &quot;每日安排&quot;">​</a></h3><ol><li>上课上完“江体科技”5min 之后，并做一些项目；完成后要求一些技术性，匹配我的性格技术栈。</li><li>物理方向，我也得想接触到下面的物理途径： <ul><li>量子力学的后续课程。</li><li>相对论的内容学习。</li><li>前沿的细分方向是啥？</li><li>PIMN 光流者。（原文，待校对）</li><li>教材依旧是“希望那斯”的书和题目。（原文，待校对）</li><li>相对论的材料是“深火热吧”。（原文，待校对）</li></ul></li><li>总而言之，都要努力！</li></ol><h2 id="四、课表" tabindex="-1">四、课表 <a class="header-anchor" href="#四、课表" aria-label="Permalink to &quot;四、课表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节次</th><th>时间</th><th>星期一</th><th>星期二</th><th>星期三</th><th>星期四</th><th>星期五</th></tr></thead><tbody><tr><td>上午第1节</td><td>08:00~08:45</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>上午第2节</td><td>08:55~09:40</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>上午第3节</td><td>10:10~10:55</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>上午第4节</td><td>11:05~11:50</td><td>物理（初三10班）</td><td></td><td></td><td></td><td></td></tr><tr><td>中午</td><td></td><td>中午休息</td><td></td><td></td><td></td><td></td></tr><tr><td>下午第5节</td><td>14:20~15:00</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>下午第6节</td><td>15:10~15:50</td><td>物理（初三4班）</td><td>物理（初三10班）</td><td>物理（初三4班）</td><td>物理（10班）</td><td>物理（初三10班）</td></tr><tr><td>下午第7节</td><td>16:00~16:50</td><td>物理（初三5班）</td><td>物理（初三5班）</td><td>物理（初三4班）</td><td></td><td></td></tr><tr><td>下午第8节</td><td>16:50~17:30</td><td>物理（初三5班）</td><td></td><td></td><td></td><td></td></tr><tr><td>课外活动</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>晚修1</td><td>19:25~20:05</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>晚修2</td><td>20:10~20:50</td><td>物理（初三4班）</td><td></td><td></td><td></td><td></td></tr><tr><td>晚修3</td><td>20:55~21:35</td><td></td><td>物理（初三10班）</td><td>物理（初三5班）</td><td>物理（初三5班）</td><td></td></tr></tbody></table><ul><li>晚上时间全部用来上课和自习！</li><li>于是是在不在校吧，这周就先不回来了。（原文，待校对）</li></ul><h2 id="五、晚上安排" tabindex="-1">五、晚上安排 <a class="header-anchor" href="#五、晚上安排" aria-label="Permalink to &quot;五、晚上安排&quot;">​</a></h2><ol><li>上完“江协”的课。</li><li>物理学的内容还是得持续学习。</li><li>教学工作流！</li><li>这个时候跟我们说开直播！</li><li>多输出些内容，发布到哪里也是个问题。</li></ol><h2 id="六、随记" tabindex="-1">六、随记 <a class="header-anchor" href="#六、随记" aria-label="Permalink to &quot;六、随记&quot;">​</a></h2><ul><li>我好像已经跟不上时代了。</li></ul>',35)])])}const _=d(r,[["render",e]]);export{b as __pageData,_ as default};
